def find_path(graph, start, goal):
    """
    Implement a path search algorithm in Python.

    The function takes a graph (as a dictionary where keys are nodes and values are lists of adjacent nodes),
    a start node, and a goal node. It returns a list of nodes from start to goal (inclusive) that follow
    existing edges, or None if the goal is unreachable.
    """
    if start not in graph or goal not in graph:
        return None

    path_stack = [(start, [start])]
    while path_stack:
        (current, path) = path_stack.pop()
        for next_node in graph[current]:
            if next_node not in path:
                if next_node == goal:
                    # Found the path to the goal
                    return path + [next_node]
                else:
                    path_stack.append((next_node, path + [next_node]))
    return None  # Return None if goal is unreachable
