def find_path(graph, start, goal):
    visited = set()  # Set to keep track of visited nodes

    def dfs(node, path):
        visited.add(node)
        if node == goal:
            return path + [node]

        for neighbor in graph[node]:
            if neighbor not in visited:
                result = dfs(neighbor, path + [node])
                if result:
                    return result
        return None

    return dfs(start, [])

